const AUDITED_BY = Symbol("auditedBy");

function markAudited(record, who) {
  record[AUDITED_BY] = who;
  return record;
}

function auditedBy(record) {
  return record[AUDITED_BY];
}

const order = { id: "ORD-7", auditedBy: "customer note" };
markAudited(order, "Chidi");
console.log(order.auditedBy, auditedBy(order));
console.log(JSON.stringify(order));

