questions.solution:
const redact = Symbol.for("shop.log.redact");

function safeForLog(value) {
  if (value === null || typeof value !== "object") return value;
  if (typeof value[redact] === "function") return value[redact]();
  return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, safeForLog(item)]));
}

class Card {
  constructor(number) { this.number = number; }
  [redact]() { return `card ending ${this.number.slice(-4)}`; }
}

console.log(safeForLog({ orderId: "ORD-7", card: new Card("4111111111111111"), redact: "keep me" }));
